def compute(vars):
    values = {
        2018: vars["v1"],
        2017: vars["v2"],
        2016: vars["v3"],
    }
    lowest_year = min(values, key=values.get)
    lowest_amount = values[lowest_year]
    return {
        "value": lowest_amount,
        "trace": {
            "values_by_year": values,
            "lowest_year": lowest_year,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None,
            },
        },
    }
